import { test, expect } from "@playwright/test";

test("BUG-20251216: TP calculation should be relative to Trigger Price, not Open Price", async ({ page }) => {
  // Parameters from the bug report
  const date = "2025-12-02";
  const strategy = "strategy12.10.1";
  const pt = "50";
  const sl = "10";
  const trg = "10";
  const candleType = "1s";
  const cutoffTime = "09:45";

  // URL to reproduce the bug
  const url = `/backtest/${date}?strategy=${strategy}&pt=${pt}&sl=${sl}&trg=${trg}&candleType=${candleType}&cutoffTime=${encodeURIComponent(cutoffTime)}`;

  // Wait for the algo API response to verify the calculation
  const algoResponsePromise = page.waitForResponse((response) => 
    response.url().includes("/api/backtest/algo") && response.status() === 200
  );

  await page.goto(url);

  const response = await algoResponsePromise;
  const data = await response.json();

  // Validate we have trades
  expect(data.algoTrades).toBeTruthy();
  expect(data.algoTrades.length).toBeGreaterThan(0);

  // Find a trade that hit TP
  // We look for a "Close Long" or "Close Short" with note "PT Hit"
  const tpTrade = data.algoTrades.find((trade: any) => 
    trade.note === "PT Hit"
  );

  // If no TP hit found in this specific day, we might need to adjust params or pick another day.
  // But the user screenshot shows trades, and the bug report implies TP levels are wrong.
  // Even if no trade hits TP, we can verify the TP level if it's logged or returned in metadata?
  // Strategy 12.10.1 returns `AlgoTradeRow[]`. It doesn't return the TP level explicitly in the row, 
  // only the execution price if hit.

  // However, the screenshot shows "Lines 35" which implies the lines are drawn based on data.
  // The frontend likely calculates the lines OR receives them.
  // If the frontend calculates the lines, the bug might be in the frontend?
  // User says "It's using the start price to establish the TP".
  // If the STRATEGY calculates the trades, and the backend returns them, then the backend logic is what matters.
  // The user says "TP is 25,576" (observed on chart).

  // Let's assume there is at least one trade that hits TP or we can infer from the logs if enabled.
  // But logs are server-side usually.

  // Strategy 12.10.1 logs detailed info.
  // If we can't find a TP hit, this test might be flaky if the price never touches the WRONG TP.
  // But given the user report, it seems the lines are visible.

  // Let's check if the response contains "startPrice" or similar metadata.
  // The `generateAlgoTrades` usually returns just rows.

  // If we assume the first trade is the one the user is looking at.
  // User says "Open is at 25,526".
  // Let's check the first candle open of the day (or 9:35 open).
  // Strategy 12.10.1 uses 9:35 open.

  // We can fetch the candles to find the 9:35 open.
  const candlesResponsePromise = page.waitForResponse((response) => 
    response.url().includes("/api/candles") && response.status() === 200
  );
  // Reload to capture candles if missed (unlikely if parallel)
  // Actually, let's just use the AlgoTrades entry price to infer the trigger.

  // Trade 1:
  // Entry = Trigger + Slippage.
  // Slippage is usually small (0.25?).
  // If we find an entry, we can back-calculate the Trigger.
  // Trigger = Entry - Slippage (Long) or Entry + Slippage (Short).

  // Then we check the Exit.
  // If Note is "PT Hit", Exit Price = TP - Slippage (Long) or TP + Slippage (Short).

  // Expected Relation:
  // TP = Trigger + PT (Long).
  // Exit = (Entry - Slip) + PT +/- Slip.

  // Let's find a PT Hit trade.
  if (tpTrade) {
    const tradeId = tpTrade.id.replace("close-", "");
    const openTrade = data.algoTrades.find((t: any) => t.id === `open-${tradeId}`);
    expect(openTrade).toBeTruthy();

    const direction = openTrade.type.includes("Long") ? "long" : "short";
    const entryPrice = openTrade.price;
    const exitPrice = tpTrade.price;
    const entrySlippage = openTrade.slippage || 0;
    const exitSlippage = tpTrade.slippage || 0;

    // Reconstruct Trigger Price
    const triggerPrice = direction === "long" 
      ? entryPrice - entrySlippage
      : entryPrice + entrySlippage;

    // Reconstruct TP Price
    const tpPrice = direction === "long"
      ? exitPrice + exitSlippage
      : exitPrice - exitSlippage;

    // Calculate effective PT distance
    const effectivePt = Math.abs(tpPrice - triggerPrice);

    console.log(`Trade ${tradeId}: Direction=${direction}, Trigger=${triggerPrice}, TP=${tpPrice}, EffectivePT=${effectivePt}`);

    // Expected PT is 50.
    // Buggy PT is likely 50 +/- TriggerOffset?
    // If Bug: TP = Open + 50.
    // Trigger = Open + 10.
    // So TP - Trigger = (Open + 50) - (Open + 10) = 40.

    // So if EffectivePT is 40, it's the bug.
    // If EffectivePT is 50, it's fixed.

    // We expect 50.
    expect(effectivePt).toBeCloseTo(parseFloat(pt), 1);
  } else {
    // Fail if no TP hit found to verify
    // But maybe the bug causes NO TP hit?
    // Or maybe we can rely on "slChanges" if stepped SL is involved?
    // The user specifically mentioned TP.

    // If no TP hit, we can't verify via executed trades.
    // Failing the test if no TP hit is found is safer than passing falsely.
    throw new Error("No trade with 'PT Hit' found. Cannot verify TP calculation.");
  }

  // Verify ZERO console errors
  const consoleErrors: string[] = [];
  page.on("console", (msg) => {
    if (msg.type() === "error") consoleErrors.push(msg.text());
  });
  expect(consoleErrors).toHaveLength(0);
});

