import { authenticate } from "./helper/auth-helpers";

test("BUG-20251216: TP calculation should be relative to Trigger Price, not Open Price", async ({ page }) => {
  // Login first
  await authenticate(page);

  // Parameters from the bug report
  const date = "2025-12-03"; // Using 03 because 02 has missing data in repo
  const strategy = "strategy12.10.1";
  const pt = "50";
  const sl = "10";
  const trg = "10";
  const candleType = "1s";
  const cutoffTime = "09:45";

  // URL to reproduce the bug
  const url = `/backtest/${date}?strategy=${strategy}&pt=${pt}&sl=${sl}&trg=${trg}&candleType=${candleType}&cutoffTime=${encodeURIComponent(cutoffTime)}`;

  await page.goto(url);

  // Wait for the calculation to complete (summary stats to appear)
  // We expect "TODAY'S NET" to be visible
  await expect(page.getByText("TODAY'S NET")).toBeVisible({ timeout: 15000 });

  // Wait a bit more for stable render
  await page.waitForTimeout(2000);

  // Get the full text content to parse values
  const bodyText = await page.evaluate(() => document.body.innerText);
  console.log("Page Text Preview:", bodyText.substring(0, 500));

  // Look for "TODAY'S NET: +XX.XX pts"
  // The layout might be "TODAY'S NET:\n+30.00 pts"
  const netMatch = bodyText.match(/TODAY'S NET:?\s*\n?\s*([+\-]?\d+\.\d+)\s*pts/i);
  // Look for "TRADES: X"
  const tradesMatch = bodyText.match(/TRADES:?\s*\n?\s*(\d+)/i);

  console.log("Net Match:", netMatch);
  console.log("Trades Match:", tradesMatch);

  if (!tradesMatch || parseInt(tradesMatch[1]) === 0) {
    throw new Error("No trades found for this day/params. Cannot verify bug.");
  }

  const totalNet = parseFloat(netMatch![1]);
  const tradeCount = parseInt(tradesMatch![1]);
  const avgProfit = totalNet / tradeCount;

  console.log(`Total Net: ${totalNet}, Trades: ${tradeCount}, Avg: ${avgProfit}`);

  // Expected Behavior (Fixed):
  // Profit = TP (50) - Slippage.
  // Buggy Behavior:
  // Profit = TP (50) - Trigger (10) - Slippage = 40 - Slippage.
  // Or if Trigger is subtracted from Open?
  // User says: TP is set relative to Open. Trigger is relative to Open.
  // If TRG=10 (Long Trigger = Open + 10).
  // If TP=50 (TP Price = Open + 50).
  // Profit = TP Price - Entry Price = (Open + 50) - (Open + 10 + Slip) = 40 - Slip.

  // So if buggy, we expect ~40.
  // If fixed, we expect ~50.

  // Fail if buggy (avg < 45)
  expect(avgProfit).toBeGreaterThan(45);

  // Verify ZERO console errors
  const consoleErrors: string[] = [];
  page.on("console", (msg) => {
    if (msg.type() === "error") consoleErrors.push(msg.text());
  });
  expect(consoleErrors).toHaveLength(0);
});

