import { describe, it, expect, vi } from "vitest";
import { runStrategy12dot10dot1 } from "../strategy12dot10dot1";
import { Candle } from "../../../backtest";

describe("BUG-20251216: TP Calculation Logic", () => {
  it("should calculate TP relative to Trigger Price, not Start Price", () => {
    // Setup candles
    // 9:30 candle
    const candles: Candle[] = [
      { time: "09:30:00", open: 100, high: 100, low: 100, close: 100, volume: 100 },
      // 9:35 candle (start price switch)
      { time: "09:35:00", open: 100, high: 100, low: 100, close: 100, volume: 100 },
      // Trigger candle (Long) - hits trigger (100 + 10 = 110)
      { time: "09:36:00", open: 100, high: 115, low: 100, close: 115, volume: 100 },
      // TP candle - goes high enough to hit TP
      { time: "09:37:00", open: 115, high: 200, low: 115, close: 200, volume: 100 },
    ];

    const startPrice = 100;
    const triggerPts = 10;
    const profitTargetPts = 50;
    const stopLossPts = 10;

    // Run strategy
    const results = runStrategy12dot10dot1(
      candles,
      startPrice,
      triggerPts,
      profitTargetPts,
      stopLossPts,
      1, // maxRoundTrips
      false // enableLogging
    );

    // Find the trade
    const closeRow = results.find(r => r.type === "Close Long");
    expect(closeRow).toBeDefined();

    // Check Exit Price
    // Expected:
    // Start (at 9:35) = 100.
    // Trigger = Start + 10 = 110.
    // TP = Trigger + 50 = 110 + 50 = 160.
    // Entry = Trigger + Slippage. (Slippage=0.25 usually).

    // If Buggy: TP = Start + 50 = 150.

    // Note: The strategy applies slippage to TP exit.
    // TP Exit Price = TP - TP_Slippage (for Long).
    // Let's assume TP_Slippage is small (e.g. 0.25).
    // Verify calculateTpSlippage in helpers if needed, but usually it's small.

    const exitPrice = closeRow!.price;
    console.log("Exit Price:", exitPrice);

    // Expect > 155 (to be safe above 150).
    // If buggy, it would be ~150.
    expect(exitPrice).toBeGreaterThan(155);
    expect(exitPrice).toBeLessThan(161); // Should be around 160
  });
});

